//! Rust port of `tests/test10.cpp`.
//!
//! Builds a set of concentric polygonal rings — ring `layer` has
//! `(layer + 3) * 2` vertices on a circle of radius `(layer + 1) * 0.3 + layer * 0.1`
//! — hands them to the earcut triangulator as a single polygon (ring 0 is the
//! outer boundary, the rest are holes) and prints the resulting triangle
//! indices.
//!
//! Usage: `test10 [n]`, where `n` defaults to 10.
//!
//! Build standalone with `rustc -O test10.rs`, or with `cargo build --release`.

#[path = "src/mapbox/mod.rs"]
mod mapbox;

use std::f64::consts::PI;
use std::io::{self, Write};

use mapbox::earcut;

/// `std::atoi` as implemented by glibc: `(int) strtol(nptr, NULL, 10)`.
///
/// Leading whitespace is skipped, an optional sign is honoured, decimal digits
/// are consumed until the first non-digit, and the `long` result is *truncated*
/// (not clamped) to `int`. That truncation is observable: `atoi("4294967297")`
/// is `1`, and `atoi("2147483648")` is `-2147483648`. Values that overflow
/// `long` itself saturate to `LONG_MAX` / `LONG_MIN` before the cast.
fn c_atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    // isspace()
    while i < bytes.len() {
        match bytes[i] {
            b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r' => i += 1,
            _ => break,
        }
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut acc: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = (bytes[i] - b'0') as i64;
        if !overflowed {
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    let value: i64 = if overflowed {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    value as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 10;
    if args.len() > 1 {
        n = c_atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    let mut layer: i32 = 0;
    while layer < n {
        let mut ring: Vec<[f64; 2]> = Vec::new();
        let radius = layer.wrapping_add(1) as f64 * 0.3;

        // `(layer + 3) * 2`, both as the loop bound and as the angle divisor.
        let count = layer.wrapping_add(3).wrapping_mul(2);

        let mut i: i32 = 0;
        while i < count {
            let angle = 2.0 * PI * i as f64 / count as f64;
            let offset = layer as f64 * 0.1;
            ring.push([
                (radius + offset) * angle.cos(),
                (radius + offset) * angle.sin(),
            ]);
            i += 1;
        }

        polygon.push(ring);
        layer = layer.wrapping_add(1);
    }

    let indices = earcut::<u32, _, _>(&polygon);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for idx in &indices {
        let _ = write!(out, "{} ", idx);
    }
    let _ = out.flush();
}

#include <iostream>
#include <vector>
#include <array>
#include "../earcut.hpp"

int main(int argc, char* argv[]) {
    int n = 10;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    std::vector<std::vector<std::array<double, 2>>> polygon;

    for (int layer = 0; layer < n; layer++) {
        std::vector<std::array<double, 2>> ring;
        double radius = (layer + 1) * 0.3;

        for (int i = 0; i < (layer + 3) * 2; i++) {
            double angle = 2.0 * M_PI * i / ((layer + 3) * 2);
            double offset = layer * 0.1;
            ring.push_back({(radius + offset) * std::cos(angle), (radius + offset) * std::sin(angle)});
        }

        polygon.push_back(ring);
    }

    auto indices = mapbox::earcut<uint32_t>(polygon);

    for (auto idx : indices) {
        std::cout << idx << " ";
    }
    return 0;
}


